            match c2.compare_exchange_weak(current, next, Ordering::SeqCst, Ordering::SeqCst) {
                Ok(_) => break,
                Err(_) => continue,
            }
        }
    });

    // Wait for both workers to finish
    handle1.join().unwrap();
    handle2.join().unwrap();

    // Verify that the counter equals two
